from pathlib import Path

import numpy as np
import pandas as pd

# Load the predictions generated by the baseline model.
predictions_path = Path("results/baseline_predictions.csv")
df = pd.read_csv(predictions_path, parse_dates=["date"])

# Calculate prediction errors.
df["rf_error_m"] = (
    df["random_forest_prediction_m"] - df["actual_gwl_m"]
)
df["rf_absolute_error_m"] = df["rf_error_m"].abs()

df["persistence_error_m"] = (
    df["persistence_prediction_m"] - df["actual_gwl_m"]
)
df["persistence_absolute_error_m"] = (
    df["persistence_error_m"].abs()
)

# 1. Overall comparison.
print("\n=== OVERALL ERROR ANALYSIS ===")
for model, error_column in [
    ("Random Forest", "rf_error_m"),
    ("Persistence", "persistence_error_m"),
]:
    errors = df[error_column]
    print(f"\n{model}")
    print(f"MAE:  {errors.abs().mean():.4f} m")
    print(f"RMSE: {np.sqrt((errors ** 2).mean()):.4f} m")
    print(f"Mean signed error: {errors.mean():.4f} m")

# 2. Observations with the largest Random Forest errors.
print("\n=== 10 LARGEST RANDOM FOREST ERRORS ===")
top_errors = df.nlargest(10, "rf_absolute_error_m")[
    [
        "date",
        "well_id",
        "actual_gwl_m",
        "random_forest_prediction_m",
        "rf_error_m",
        "rf_absolute_error_m",
    ]
]
print(top_errors.to_string(index=False))

# 3. Performance by year.
df["year"] = df["date"].dt.year

yearly = df.groupby("year").apply(
    lambda group: pd.Series({
        "observations": len(group),
        "RF_MAE_m": group["rf_absolute_error_m"].mean(),
        "Persistence_MAE_m": group["persistence_absolute_error_m"].mean(),
        "RF_RMSE_m": np.sqrt((group["rf_error_m"] ** 2).mean()),
    }),
    include_groups=False,
).reset_index()

print("\n=== PERFORMANCE BY YEAR ===")
print(yearly.round(4).to_string(index=False))

# Save results for later research analysis.
output_path = Path("results/baseline_error_analysis.csv")
yearly.to_csv(output_path, index=False)
print(f"\nSaved yearly analysis to {output_path}")
